window.RP_SESSION={"id":"S-d6d2031a8ea1","messages":[{"id":"RP-0094950","time":"2026-03-29T19:23:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 그루터기에 누워있는다. 한스의 마법이 풀려 다시 '사람'과 제대로 대화 못하는 상태인게...","characters":["P-6eeed2b4661f"]},{"id":"RP-0094951","time":"2026-03-29T19:24:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-말하지 말 것.","characters":["P-6eeed2b4661f"]},{"id":"RP-0094952","time":"2026-03-29T19:24:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"잘 모르겠다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0094953","time":"2026-03-29T19:24:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '머리 아프다... 어지럽고.'","characters":["P-6eeed2b4661f"]},{"id":"RP-0094954","time":"2026-03-29T19:25:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"에스텔은 그루터기 끄트머리에 살며시 앉아 멍한 표정으로 모닥불을 바라보았다. \n\n일렁거림. 아스라이 춤추는 불꽃.\n\n퍽 아름답게 보였으나, 에스텔은 좀 처럼 일말의 고뇌를 떨쳐내지 못한다.","characters":["P-b522cca806d0"]},{"id":"RP-0094955","time":"2026-03-29T19:26:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" -`말하지 말 것`\n\n  마지막으로 사람과 사람의 언어로 제대로 대화한 적은 기억조차 안 나는 어린 시절이었을 뿐이라 제법 신났었나보다.\n\n -`말하지 말 것`","characters":["P-6eeed2b4661f"]},{"id":"RP-0094956","time":"2026-03-29T19:29:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '피곤해'","characters":["P-6eeed2b4661f"]},{"id":"RP-0094957","time":"2026-03-29T19:32:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-b522cca806d0"]},{"id":"RP-0094958","time":"2026-03-29T19:32:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"우물에서 나올때 부터 줄곧 같은 표정","characters":["P-b522cca806d0"]},{"id":"RP-0094959","time":"2026-03-29T19:34:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 가만-히 누워있자니.","characters":["P-6eeed2b4661f"]},{"id":"RP-0094960","time":"2026-03-29T19:34:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 주변 동물들이 한 마리, 두 마리...","characters":["P-6eeed2b4661f"]},{"id":"RP-0094961","time":"2026-03-29T19:35:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-6eeed2b4661f"]},{"id":"RP-0094962","time":"2026-03-29T19:35:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'아도니스'의 매력 판정 :\n[2] + [3] = [5]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0094963","time":"2026-03-29T19:35:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"한참 가만히 있으니까 5마리 정도 왔다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0094964","time":"2026-03-29T19:35:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"근데 안 얌전해.","characters":["P-6eeed2b4661f"]},{"id":"RP-0094965","time":"2026-03-29T19:36:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아야... 그만 때려. 라고 전하고 싶지만, 자연의 언어로 말하기에도 너무 지쳤다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0094966","time":"2026-03-29T20:01:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0094967","time":"2026-03-29T20:01:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"따그닥 따그닥","characters":[]},{"id":"RP-0094968","time":"2026-03-29T20:01:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이것은 입에서 내는 소리다","characters":[]},{"id":"RP-0094969","time":"2026-03-29T20:01:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0094970","time":"2026-03-29T20:02:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"여기는 왜 시체들밖에 없소?\"","characters":[]},{"id":"RP-0094971","time":"2026-03-29T20:02:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"시체? 어디요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0094972","time":"2026-03-29T20:02:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"제가 되살릴게요!\"","characters":["P-c93f55c91873"]},{"id":"RP-0094973","time":"2026-03-29T20:03:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아하하...! 시체라뇨! 전 파릇파릇한 소녀인걸요!\"\n\n에스텔은 벌떡 일어나 방긋 웃으며 가슴을 내밀었다. 과장된 동작이었다.","characters":["P-b522cca806d0"]},{"id":"RP-0094974","time":"2026-03-29T20:04:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-b522cca806d0"]},{"id":"RP-0094975","time":"2026-03-29T20:04:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"오\"","characters":[]},{"id":"RP-0094976","time":"2026-03-29T20:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭐야, 안 죽었네?\"","characters":["P-c93f55c91873"]},{"id":"RP-0094977","time":"2026-03-29T20:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아이고, 이런. 버릇없게시리. 안 돌아가셨네?\"","characters":["P-c93f55c91873"]},{"id":"RP-0094978","time":"2026-03-29T20:04:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"꼬맹이군\"","characters":[]},{"id":"RP-0094979","time":"2026-03-29T20:04:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"전기를 맞긴 했지만 제 장점 중 하나가 튼튼하다는 거랍니다⸺!\"","characters":["P-b522cca806d0"]},{"id":"RP-0094980","time":"2026-03-29T20:04:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"안죽었다면 다행인데\"","characters":[]},{"id":"RP-0094981","time":"2026-03-29T20:05:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"왜 울쌍이죠?\"","characters":[]},{"id":"RP-0094982","time":"2026-03-29T20:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"와, 저도 때려볼래요!\"","characters":["P-c93f55c91873"]},{"id":"RP-0094983","time":"2026-03-29T20:05:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"아도니스는 동물들","characters":["P-6eeed2b4661f"]},{"id":"RP-0094984","time":"2026-03-29T20:05:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-6eeed2b4661f"]},{"id":"RP-0094985","time":"2026-03-29T20:05:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'아도니스'의 매력 판정 :\n[3] + [3] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0094986","time":"2026-03-29T20:06:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그새 한 마리 더 추가 된 6마리에 쌓인채 누워있다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0094987","time":"2026-03-29T20:06:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"델타인의 광기는 이길수 없단건가","characters":[]},{"id":"RP-0094988","time":"2026-03-29T20:06:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"울상이라뇨? 전 언제나 행복하고 즐거운걸요...!\"\n\n싱긋웃으며 제자리에서 빙그르르 돈다. 드레스의 밑단이 움직임을 따라 살랑인다.\n\n\"그렇다고 때리진 말아주세요...?! 아무리 저라도 아픈건 아프답니다. 아하하...!\"","characters":["P-b522cca806d0"]},{"id":"RP-0094989","time":"2026-03-29T20:06:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0094990","time":"2026-03-29T20:07:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"지끈지끈!","characters":["P-6eeed2b4661f"]},{"id":"RP-0094991","time":"2026-03-29T20:07:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"꼬맹...아가씨, 마력은 숨길수 없소\"","characters":[]},{"id":"RP-0094992","time":"2026-03-29T20:07:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0094993","time":"2026-03-29T20:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엥? 제가 션 씨한테 들었는데 아픈 건 몸에 좋대요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0094994","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"나를 기절시키지 못하는 고통은… 뭐랬지?\"","characters":["P-c93f55c91873"]},{"id":"RP-0094995","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"벌떡 서게 만든다?\"","characters":["P-c93f55c91873"]},{"id":"RP-0094996","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"\"?\"","characters":[]},{"id":"RP-0094997","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"네...?\"","characters":["P-b522cca806d0"]},{"id":"RP-0094998","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 다시 일어서게 만든다!\"","characters":["P-c93f55c91873"]},{"id":"RP-0094999","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0095000","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"포기를 모르고 다시 일어서게 만든다고 했어요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0095001","time":"2026-03-29T20:08:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-b522cca806d0"]},{"id":"RP-0095002","time":"2026-03-29T20:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭐, 비슷하지 않나요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0095003","time":"2026-03-29T20:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 동물들 뚫고 벌떡 일어나기.\n\n '아프다...'","characters":["P-6eeed2b4661f"]},{"id":"RP-0095004","time":"2026-03-29T20:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아무튼, 저도 분홍머리 아가씨에게 더 좋은 상태를 선사하고 싶었던 거죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0095005","time":"2026-03-29T20:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"몸이 아프면 머리가 아픈 것도 사라지시고, 저에 대한 증오와 멸시만 남으시지 않을까요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0095006","time":"2026-03-29T20:11:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아, 아하하...역시 그런 뜻이 맞겠죠...! 저도 글쎄, 이상한 생각을 해버렸잖아요⸺?\"\n\n아하하하, 점점 작아져가는 어색한 웃음으로 한참을 입을 벌리고 있던 에스텔은, 불꽃을 멍하니 바라보다가 이내 다시 입을 움직였다.\n\n\"으흐흠⸻, 다들 감이 좋으신 것 같아요! 아니면 제가 감정을 잘 못 숨긴다던가~? 너무 솔직해서 탈이라니까요, 아하하.\"","characters":["P-b522cca806d0"]},{"id":"RP-0095007","time":"2026-03-29T20:12:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"증오와, 멸시인가요?\"\n\n멍하니 허공을 바라보던 에스텔은, 이내 부드러운 웃음을 지으며 소리내어 웃었다.\n\n\"아하하, 가장 순수한 상태의 감정에 대해 그렇게도 표현 할 수 있겠네요.\"","characters":["P-b522cca806d0"]},{"id":"RP-0095008","time":"2026-03-29T20:12:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-6eeed2b4661f"]},{"id":"RP-0095009","time":"2026-03-29T20:13:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'아도니스'의 체력 판정 :\n[5] + [0] = [5]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0095010","time":"2026-03-29T20:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 양손을 허리에 척 얹고 고개를 끄덕였다.\n\n\"암, 물론이지요.\"\n\n그러다가 그는 눈을 뜨고 위아래로 에스텔을 훑어보더만 고개를 갸우뚱거렸다.\n\n\"근데 누구세요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0095011","time":"2026-03-29T20:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"웨이러 미닛, 후 아 유?","characters":["P-c93f55c91873"]},{"id":"RP-0095012","time":"2026-03-29T20:13:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 일어나서 비틀비틀 걷다가 흙 위에 다시 엎어지기.\n\n'...이 쪽이 좀 더 편할지도.'","characters":["P-6eeed2b4661f"]},{"id":"RP-0095013","time":"2026-03-29T20:13:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 놀랍게도 흙이 차가워서 두통 완화에 도움이 되었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0095014","time":"2026-03-29T20:14:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아하하, 제 정신도 참...아직 자기 소개도 안했었네요!\"\n\n에스텔은 방긋한 얼굴로 델타인의 지척까지 다가가 손을 뻗었다.\n\n\"에스텔, 에스텔 벨라시타라고 해요. 기사도 아니고, 성직자도 아니지만. 성기사가 되고자 한답니다...!\"","characters":["P-b522cca806d0"]},{"id":"RP-0095015","time":"2026-03-29T20:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어유, 정신 좀 차리셔야죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0095016","time":"2026-03-29T20:15:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"요즘 세상이 얼마나 무서운데요. 저도 외벽을 청소하다 보면 간혹 돌멩이가 날아올 때가 있답니다?\"","characters":["P-c93f55c91873"]},{"id":"RP-0095017","time":"2026-03-29T20:15:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그렇게 벽에서 떨어지고 나면 골이 울리는데, 그런 날 밤에는 꼭 악마가 찾아오곤 하죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0095018","time":"2026-03-29T20:16:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아 참, 그럼 신입이겠네요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0095019","time":"2026-03-29T20:16:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 에스텔에게 들고 있던 빗자루를 쥐어주었다.","characters":["P-c93f55c91873"]},{"id":"RP-0095020","time":"2026-03-29T20:16:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭐해, 너도 청소해야지.\"","characters":["P-c93f55c91873"]},{"id":"RP-0095021","time":"2026-03-29T20:17:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"와아...돌맹이라니, 아팠겠어요. 아, 네...신입이랍니다?\"\n\n에스텔은 방긋 웃으며 빗자루를 건내받고는 멍한 표정으로 바라보다가, 이내 저항없이 웃어버렸다.\n\n\"아하하! 그렇죠. 청소는 중요한 일이니까요!\"","characters":["P-b522cca806d0"]},{"id":"RP-0095022","time":"2026-03-29T20:17:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어허, 길드의 가사노동은 신입의 덕목!\"","characters":["P-c93f55c91873"]},{"id":"RP-0095023","time":"2026-03-29T20:17:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"장난스러운 게 아니라구!\"","characters":["P-c93f55c91873"]},{"id":"RP-0095024","time":"2026-03-29T20:18:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"장난이라뇨! 전 언제나 진심이랍니다!\"","characters":["P-b522cca806d0"]},{"id":"RP-0095025","time":"2026-03-29T20:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"밀대와 행주 걸레를 양손에 들고 두 팔을 하늘을 향해 뻗었다.\n\n\"이상한 생각하기 전에 빨리 뛰어!\"","characters":["P-c93f55c91873"]},{"id":"RP-0095026","time":"2026-03-29T20:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"먼지가 보이면 스텔라 씨나 카프리제 씨가 네 엉덩이를 뻥뻥 걷어찰 거라구!\"","characters":["P-c93f55c91873"]},{"id":"RP-0095027","time":"2026-03-29T20:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그리고 다락방에는 접근하지 말도록, 신입! 거긴 사람을 잡아먹는 식인 괴물이 산다고?\"","characters":["P-c93f55c91873"]},{"id":"RP-0095028","time":"2026-03-29T20:20:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"에스텔은 델타인의 말대로 청소를 진행하였으나. 그녀의 입이 닫히는 일은 한 순간도 없었다.\n\n\"와아, 여긴 먼지들이 정말 많네요. 먼지 청소하니까 생각난건데, 제가 몇 년 전에 여관에서 묵었을때말이죠?그때돈이없었어서가사노동으로한달동안일했는데, 그때 이후로이런일에꽤나익숙해져서⸻\"\n\n입이 닫히는 일은 없었다.","characters":["P-b522cca806d0"]},{"id":"RP-0095029","time":"2026-03-29T20:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"섣불리 다가갔다간 너도 하얀 천을 뒤집어 쓴 괴수에게 잡아먹힌다!\"","characters":["P-c93f55c91873"]},{"id":"RP-0095030","time":"2026-03-29T20:20:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인 또한 아랑곳 않고 길드 생활 꿀팁을 쉴새 없이 내뱉었다.","characters":["P-c93f55c91873"]},{"id":"RP-0095031","time":"2026-03-29T20:22:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그것의 8할은 써먹을 데가 전혀 없는 헛소리였으나 옷에 묻은 핏자국을 세탁하는 법, 조심해야할 길드원, 성질이 더러운 길드원, 그리고 묵은 때를 지우는 법 따위의 2할 정도는 예상 외로 괜찮았다.","characters":["P-c93f55c91873"]},{"id":"RP-0095032","time":"2026-03-29T20:22:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아하하, 식인 괴물인가요? 식인 괴물 하니까 생각난건데, 작년 즈음에 작은 마을에서 있었던 일이거든요. 그때 촌장님이 식인 괴물이라고 겁을 엄청주면서 숲에 들어가지 말라길래 바들바들 떨면서 밤에 몰래 숲에 가서 괴물을토벌하려했는데, 그게사실은괴물소리를따라내던앵무새였던거있죠.제가걔를휙하고잡아서자세히살펴보니까다리가묶여있는거에요.그래서그걸풀어서숲에다가풀어줬는데⸻\"","characters":["P-b522cca806d0"]},{"id":"RP-0095033","time":"2026-03-29T20:22:00+09:00","room":"RP","name":"한스 니벨룽겐","profile":"한스 니벨룽겐","identity":"unresolved","type":"dialogue","body":"래퍼인가요?","characters":[]},{"id":"RP-0095034","time":"2026-03-29T20:23:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"랩하니까생각난건데에스텔은재작년즈음에어떤마을에서가희대회가열린다는걸알게되고거기서","characters":["P-b522cca806d0"]},{"id":"RP-0095035","time":"2026-03-29T20:23:00+09:00","room":"RP","name":"한스 니벨룽겐","profile":"한스 니벨룽겐","identity":"unresolved","type":"dialogue","body":"음","characters":[]},{"id":"RP-0095036","time":"2026-03-29T20:24:00+09:00","room":"RP","name":"한스 니벨룽겐","profile":"한스 니벨룽겐","identity":"unresolved","type":"dialogue","body":"아리차야 미안하다","characters":[]},{"id":"RP-0095037","time":"2026-03-29T20:24:00+09:00","room":"RP","name":"한스 니벨룽겐","profile":"한스 니벨룽겐","identity":"unresolved","type":"dialogue","body":"저러니 마법 음량 줄여달라고 했구나","characters":[]},{"id":"RP-0095038","time":"2026-03-29T20:24:00+09:00","room":"RP","name":"한스 니벨룽겐","profile":"한스 니벨룽겐","identity":"unresolved","type":"dialogue","body":"내 잘못이었어....","characters":[]},{"id":"RP-0095039","time":"2026-03-29T20:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 그거! 나도 LA에 있었을, 그러니까, 로스트엔젤 기사단이란 곳에 있었을 때—\"\n\n델타인도 곧이어 자신이 기사단 종자, 대장간 막내, 목수 겸 짐꾼으로 일하던 시절을 떠벌떠벌거리기 시작했다.","characters":["P-c93f55c91873"]},{"id":"RP-0095040","time":"2026-03-29T20:25:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"아아악!\"\n\n 안 그래도 두통 때문에 고생중인데 너무 시끄러워ㅠㅠ","characters":["P-6eeed2b4661f"]},{"id":"RP-0095041","time":"2026-03-29T20:26:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"쉿!\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0095042","time":"2026-03-29T20:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"—그래서 결국 거대 민물 곰치를 초록 모자와 빨간 모자, 그리고 드라고니안과 같이 잡게 된 거지.\"","characters":["P-c93f55c91873"]},{"id":"RP-0095043","time":"2026-03-29T20:26:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"털썩.","characters":["P-6eeed2b4661f"]},{"id":"RP-0095044","time":"2026-03-29T20:26:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"와아, 로스트엔젤기사단아시는구나.저도그근처에서지냈던적이있는데그분들갑옷이정말멋진거있죠?그래서한번만입어봐도되냐고사정사정했는데안된다고하길래한달동안하루세번씩찾아가봤단말이에요⸻\"","characters":["P-b522cca806d0"]},{"id":"RP-0095045","time":"2026-03-29T20:27:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"어후","characters":[]},{"id":"RP-0095046","time":"2026-03-29T20:27:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 흣된 희생이었다.(아님)","characters":["P-6eeed2b4661f"]},{"id":"RP-0095047","time":"2026-03-29T20:27:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0095048","time":"2026-03-29T20:27:00+09:00","room":"RP","name":"루체","profile":"루체","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-0095049","time":"2026-03-29T20:29:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"—그래서 내가 그 드워프 아저씨가 결국 수염이 잘려서 죽겠다고 하시길래, 독버섯으로 수프를 끓여드렸더랬지. 근데 그 수프를 먹으니 죽진 않고 갑자기 몸이 쑥쑥 자라는 거 있지? 알고 보니 그게 버섯이 아니라—\"","characters":["P-c93f55c91873"]},{"id":"RP-0095050","time":"2026-03-29T20:31:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 야! 분홍머리! 너 청소 제대로 안 해?\"","characters":["P-c93f55c91873"]},{"id":"RP-0095051","time":"2026-03-29T20:31:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"감히 나를 이야기 하게 만들어서 정신을 다른 곳에 팔게 하다니… 이 간악한 녀석 같으니!\"","characters":["P-c93f55c91873"]},{"id":"RP-0095052","time":"2026-03-29T20:32:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"후… 용서치 않겠다.\"","characters":["P-c93f55c91873"]},{"id":"RP-0095053","time":"2026-03-29T20:32:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" -촉수와 분홍...\n\n By. 다잉메세지.","characters":["P-6eeed2b4661f"]},{"id":"RP-0095054","time":"2026-03-29T20:34:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아하하, 그 버선에 그런 효능이 있었던건가요? 아 참, 독버섯 하니까 생각난건데, 제가 저번에 숲에서 길을 잃고 식량도 다 떨어져서 어쩔 수 없이 버섯을 따서 먹었는데요. 그때 먹은 버섯이 참 맛있긴했는데 먹은 뒤에 온몸이 마비되어서 세시간동안제자리에 누워있을수밖에없었는데그때정말위험했단말이죠.누워서움직이질못하는데 몬스터가 나타나서⸻ 네에? 청소는 하구있는데요?\"\n\n에스텔은 먼지를 털다가 의아하다는 표정으로 고개를 갸웃거렸다.\n\n\"먼지하니까생각난건데아이건말했던건가요?그러니까여관을청소할때있던일인데술을마시고취해서고주망태로바닥에토사물을흩뿌린분이계셨는데그걸치우려고한시간동안걸레질을하고있었는데그랬더니여관주인아주머니께서이건그렇게하는게아니라면서약초몇개를넣어서청소가빡빡잘되는액체를만들어주셨는데그게기억에남아서아직도몇개씩챙겨다닌단말이죠.지금쓰고있는것도그거에요! 그러니까그걸어떻게만드는거냐면⸻\"","characters":["P-b522cca806d0"]},{"id":"RP-0095055","time":"2026-03-29T20:43:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"!의지","characters":["P-b522cca806d0"]},{"id":"RP-0095056","time":"2026-03-29T20:43:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'에스텔 벨라시타'의 의지 판정 :\n[8] + [1] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0095057","time":"2026-03-29T20:43:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"\"아하하, 제가 말이 너무 많았을까요...?\"","characters":["P-b522cca806d0"]},{"id":"RP-0095058","time":"2026-03-29T20:44:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" '살려줘...'\n\n 이미 두통으로 죽었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0095059","time":"2026-03-29T22:03:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"그렇게 에스텔은 청소를 얼추 끝냈다.\n\n한참 침울해져 있던 기분도, 한 바탕 즐거운 대화를 쏟아내니 마음 속 어딘가에 묻어둔듯하다.\n\n그래, 묻어뒀다.","characters":["P-b522cca806d0"]},{"id":"RP-0095060","time":"2026-03-29T22:03:00+09:00","room":"RP","name":"에스텔 벨라시타","profile":"샤를로타 롯테","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b522cca806d0"]}]};
